# 遍历字典:items() 同时拿到键和值
d = {'apple': 3, 'banana': 5, 'cherry': 2}
for k, v in d.items():
    print(f"{k}:{v}")

# 统计单词出现次数:用字典存 单词->次数
words = input().split()
count = {}
for w in words:
    count[w] = count.get(w, 0) + 1
# 按第一次出现顺序输出
seen = set()
for w in words:
    if w not in seen:
        seen.add(w)
        print(w, count[w])
